#include <bits/stdc++.h>
using namespace std;
#define int long long
#define endl "\n"
const int INF = 4e18;
int func(int mid, int segments, int k, vector<int> &pref){
    int len = mid*2+((segments-mid)*3);
    int ans = 0;
    ans += 3*(pref[k+len]-pref[k]);
    ans += (pref[k+2*mid]-pref[k]);
    return ans;
}
void solve(){
    int n;
    cin >> n;
    
    vector<int> a(3*n+1,1e18);
    
    for(int i=1;i<=3*n;i++) cin >> a[i];
    sort(a.begin(),a.end(),greater<>());
    
    int sum = 0;
    vector<int> pref(3*n+1,0);
    for(int i=1;i<=3*n;i++){
        pref[i]=a[i]+pref[i-1];
    }
    
    int maxi = 0;
    for(int k=0;k<=n;k++){
        int cur = 6*pref[k];
        int segments = n-k;
        int l=0, r=n-k;
        int ans = 0;
        while(l<=r){
            int mid = (l+r)/2;
            if(mid==n-k) break;
            if(func(mid,segments,k,pref)<=func(mid+1,segments,k,pref)){
                ans=mid+1;
                l=mid+1;
            }
            else r=mid-1;
        }
        cur+=func(ans,segments,k,pref);
        maxi = max(maxi,cur);
    }
    cout << maxi << endl;
}
signed main() {
	int t= 1; cin >> t;
	while(t--){
	    solve();
	    
	}

}
